<template>
  <view class="content">
    <view class="Head">
      <view
        style="
          width: 20%;
          height: 100%;
          display: flex;
          justify-content: center;
          align-items: center;
          padding-left:60rpx;
        "
      >
        <image
          :src="userInfo.avatarUrl"
          style="width: 100rpx; height: 100rpx;border-radius: 50%;"
        ></image>
      </view>
      <view
        style="
          width: 80%;
          height: 100%;
          display: flex;
          flex-direction: column;
          justify-content: center;
          align-items: flex-start;
          color: #fff;
          font-size: 40rpx;
          font-family: '黑体';
          margin-left:20upx;
        "
      >
        <view>
          {{ userInfo.userNike }}
        </view>
        <view v-if="deviceList.length==0" style="font-size:30upx;color:#ccc;margin-top:10upx"> 未绑定设备</view>
      </view>
      <!-- <view style="position: absolute;right:40rpx;top:40rpx;">
        <image
          src="../../../static/img/saoma.png"
          style="width: 70rpx; height: 70rpx"
          @click="scanQRCode"
        ></image>
      </view> -->
        
    </view>
    <view class="container">
      <u-cell-group>
        <u-cell
          v-if="!token"
          size="large"
          icon="account-fill"
          title="登录"
          :iconStyle="{fontSize:'40rpx',marginRight:'10rpx',color:'#4399ff'}"
          isLink
          @click="show = true"
        ></u-cell>
        <u-cell
          size="large"
          icon="scan"
          title="扫一扫设备"
          :iconStyle="{fontSize:'40rpx',marginRight:'10rpx',color:'#4399ff'}"
          isLink
          @click="scanQRCode"
        ></u-cell>
        <u-cell
          size="large"
          icon="question-circle"
          title="睡眠带产品说明书"
          :iconStyle="{fontSize:'34rpx',marginRight:'10rpx',color:'#4399ff'}"
          isLink
          @click="goProduct"
        ></u-cell>
        <u-cell
          size="large"
          icon="question-circle"
          title="CBTi使用建议"
          :iconStyle="{fontSize:'34rpx',marginRight:'10rpx',color:'#4399ff'}"
          isLink
          @click="gocbti"
        ></u-cell>
        <u-cell
          size="large"
          icon="error-circle"
          title="睡眠带信息"
          :iconStyle="{fontSize:'34rpx',marginRight:'10rpx',color:'#4399ff'}"
          isLink
           @click="gobindDevice()"
        ></u-cell>
        <u-cell
          size="large"
          icon="coupon"
          title="睡眠带解绑"
          :iconStyle="{fontSize:'40rpx',marginRight:'10rpx',color:'#4399ff'}"
          isLink
          @click="unbindDevice"
        ></u-cell>
        <u-cell
          size="large"
          icon="account"
          title="个人信息"
          :iconStyle="{fontSize:'40rpx',marginRight:'10rpx',color:'#4399ff'}"
          isLink
          @click="gouser"
        ></u-cell>
        <u-cell
          size="large"
          icon="phone"
          title="联系方式"
          :iconStyle="{fontSize:'40rpx',marginRight:'10rpx',color:'#4399ff'}"
          isLink
           @click="gophone"
        ></u-cell>
      </u-cell-group>
    </view>
    <u-modal
      :show="show1"
      title="睡眠带绑定设备"
      :showCancelButton="true"
      @cancel="cancel1"
      @confirm="confirm1"
    >
      <u--input
        placeholder="请输入睡眠带设备号"
        v-model="value"
        border="surround"
        clearable
      ></u--input>
    </u-modal>
    <u-modal
      :show="showhj"
      title="环境检测仪绑定设备"
      :showCancelButton="true"
      @cancel="cancelhj"
      @confirm="confirmhj"
    >
      <u--input
        placeholder="请输入环境检测仪设备号"
        v-model="value11"
        border="surround"
        clearable
      ></u--input>
    </u-modal>
    <u-notify ref="uNotify" message="Hi uView"></u-notify>
    <u-modal
      :show="show2"
      title="联系我们"
      :showCancelButton="true"
      @cancel="cancel2"
      @confirm="confirm2"
    >
      <view>
        <view style="color:red"> 该APP需要搭配睡眠带跟环境检测仪使用 </view>
        <view> 如需购买或有问题请联系客服</view>
        <view>
          电话：18858566948 
        </view>
          
        <view> 邮箱号：3696779493@qq.com </view>
      </view>
    </u-modal>
    <u-popup :show="showPopup" @close="close" @open="open">
          <view style="width:100%;height:120upx;background: #2c2c2c;color:#ccc;display: flex;justify-content: center;align-items: center;" >请选择解绑设备</view>
          <view style="width:100%;height:1upx;background: #E7e7e7;"></view>
            <view v-for="(item,index) in deviceList" :key="index" style="width:100%;height:160upx;background: #2c2c2c;color:#fff;display: flex;justify-content: center;align-items: center;border-bottom:1px solid #E7e7e7" @click="jiebang(item)">
                <view v-if="!item.deviceName">睡眠带{{ index+1 }}</view>
                <view v-else>{{item.deviceName}}</view>
            </view>
            <view style="width:100%;height:1upx;background: #E7e7e7;"></view>
            <view style="width:100%;height:120upx;background: #2c2c2c;color:#fff;display: flex;justify-content: center;align-items: center;" @click="showPopup=false">取消</view>
		</u-popup>
    <u-popup :show="show" @close="close" @open="open" mode="center">
      <view style="width:100%;min-height:250rpx;position: relative;display: flex;justify-content: center;align-items: center;">
        <view style="display:flex" >
          <u-icon name="phone-fill" color="#2979ff" size="35"></u-icon>
          <button style="background: transparent;
                padding: 0;
                font-size: 16px;margin-left:20upx"  open-type="getPhoneNumber" @getphonenumber="getPhoneNumber">手机号码快捷登录</button>
        </view>
        <u-loading-icon v-if="isLoading" mode="circle" color="#2979ff" size="28"></u-loading-icon>
      </view>
    </u-popup>
  </view>
</template>

<script>
export default {
  data() {
    return {
      userInfo: {
        userId: "",
        userNike: "",
        avatarUrl:""
      },
      token: null, // 登录状态
      show: false,
      show1: false,
      value: "",
      show2: false,
      showhj:false,
      value11:'',
      deviceList:[],
      showPopup:false,
      isLoading: false
    };
  },
  onShow() {
    // 检查登录状态
    const token = uni.getStorageSync('mytoken');
    if (token) {
      this.token = token;
      if(uni.getStorageSync('userInfo')){
        this.userInfo = uni.getStorageSync('userInfo')
        this.getDevice()
      }
    } else {
      this.token = null;
      this.userInfo = {
        userId: "",
        userNike: "未登录",
        avatarUrl:""
      };
    }
  },
  onLoad() {},
  methods: {
    getPhoneNumber(e) {
      this.isLoading = true;
      uni.request({
        url: `https://isleepagent.com:444/sleepapp/wx/user/bindPhoneNumber?code=${e.detail.code}`, // 这里是自己的接口地址
        method: 'GET',
        header: {
          "content-type": "application/json",
          token: uni.getStorageSync('mytoken')
        },
        success: (response) => {
          console.log('获取手机号成功', response);
          if (response.data.code === 200) {
            uni.setStorageSync('mytoken', response.data.data.token);
            uni.setStorage({
              key: "userInfo",
              data: response.data.data,
            });
            this.userInfo = response.data.data;
            this.token = response.data.data.token;
            uni.showToast({
              title: "登录成功!",
              icon: "none",
              duration: 2000
            });
            this.getDevice();
          } else {
            uni.showToast({
              title: response.data.msg || "登录失败，请重试",
              icon: "none",
              duration: 2000
            });
          }
        },
        fail: (err) => {
          console.error('登录失败', err);
          uni.showToast({
            title: "登录失败，请重试",
            icon: "none",
            duration: 2000
          });
        },
        complete: () => {
          this.isLoading = false;
          this.show = false;
        }
      });
    },
    toast() {
      this.show2 = true;
      // uni.showToast({
      // 		title:"有问题请联系客服",
      // 		icon: 'none',
      // 		duration: 3000,
      // 		mask: true,
      //  });
    },
    logout() {
      this.show = true;
    },
    bindDevice() {
      this.show1 = true;
    },
    close(){
      
    },
    open(){

    },
	goProduct(){
		  uni.navigateTo({
		        url: '/pages/tabbar-3-detial/tabbar-3-release/product'
		      });
	},
	gocbti(){
		  uni.navigateTo({
		       url: '/pages/tabbar-3-detial/tabbar-3-release/cbti'
		      });
	},
	gouser(){
		  uni.navigateTo({
		       url: '/pages/tabbar-3-detial/tabbar-3-release/user'
		      });
	},
	gophone(){
		  uni.navigateTo({
		       url: '/pages/tabbar-3-detial/tabbar-3-release/phone'
		      });
	},
	gobindDevice(){
    if(this.deviceList.length==0){
           return uni.showToast({
              title:"暂无绑定设备",
              icon: 'none',
              duration: 3000,
              mask: true,
          });
      }
		  uni.navigateTo({
		       url: '/pages/tabbar-3-detial/tabbar-3-release/bindDevice'
		      });
	},
  getDevice(){
    uni.request({
        url: "https://isleepagent.com:444/sleepapp/user/getUserDeviceList", //仅为示例，并非真实接口地址。
        data: {'deviceType':1},
        header: {
          "content-type": "application/json",
          token:uni.getStorageSync('mytoken')
        },
        method: "GET",
        success: (res) => {
          this.deviceList = res.data.data
        },
        fail: (res) => {},
      });
  },
  unbindDevice(){
      if(this.deviceList.length==0){
           return uni.showToast({
              title:"暂无绑定设备",
              icon: 'none',
              duration: 3000,
              mask: true,
          });
      }
      this.showPopup = true
    
    },
    jiebang(item){
  var _this = this
      uni.showModal({
          title: '解绑设备',
          content: '确认执行此操作吗？',
          success: function (res) {
              if (res.confirm) {
                    uni.request({
                      url: `https://isleepagent.com:444/sleepapp/user/unbind?deviceId=${item.deviceId}`, //仅为示例，并非真实接口地址。
                      header: {
                        "content-type": "application/json",
                        token:uni.getStorageSync('mytoken')
                      },
                      method: "GET",
                      success: (res) => {
                        if (res.data.code == 500) {
                          _this.$refs.uNotify.show({
                            // top: 20,
                            type: "error",
                            message: res.data.msg,
                            duration: 1000 * 3,
                            fontSize: 20,
                            safeAreaInsetTop: true,
                          });
                        }
                        if (res.data.code == 200) {
                          _this.$refs.uNotify.show({
                            top: 0,
                            type: "success",
                            message: "解绑成功",
                            duration: 1000 * 3,
                            fontSize: 20,
                            safeAreaInsetTop: true,
                          });
                          _this.value = ''
                        }
                        _this.getDevice()
                        _this.showPopup = false
                      },
                      fail: (res) => {},
                    });
              } else if (res.cancel) {
                  console.log('用户点击取消');
                  // 这里执行取消后的操作
              }
          }
      });
    },
    bindDevice1(){
      this.showhj = true;
    },
    confirm2() {
      this.show2 = false;
    },
    cancel2() {
      this.show2 = false;
    },
    saoma(){
      uni.authorize({
        scope: 'scope.camera',
        success() {
            // 用户同意授权
            this.scanQRCode();
        },
        fail() {
            // 用户拒绝授权
            uni.showToast({
                title: '您拒绝了授权',
                icon: 'none'
            });
        }
    });
    },
    scanQRCode() {
		var _this = this
        uni.scanCode({
            success(res) {
                if (res.result) {
                    // 扫描成功，处理二维码内容
                    console.log('扫描结果：', res.result);
                    var postData = {
                    
                      deviceId: res.result,
                    };
                    uni.request({
                      url: "https://isleepagent.com:444/sleepapp/user/bind", //仅为示例，并非真实接口地址。
                      data: postData,
                      header: {
                        "content-type": "application/json",
                        token:uni.getStorageSync('mytoken')
                      },
                      method: "POST",
                      success: (res) => {
                        console.log(res)
                        if (res.data.code == 500) {
                          _this.$refs.uNotify.show({
                            top: 20,
                            type: "error",
                            message: "绑定失败",
                            duration: 1000 * 3,
                            fontSize: 20,
                            safeAreaInsetTop: false,
                          });
                        }
                        if (res.data.code == 200) {
                          _this.$refs.uNotify.show({
                            top: 20,
                            type: "success",
                            message: "绑定成功",
                            duration: 1000 * 3,
                            fontSize: 20,
                            safeAreaInsetTop: false,
                          });
                          _this.getDevice()
                          // uni.setStorage({
                          //   key: "userInfo",
                          //   data: res.data.data,
                          // });
                        }
                      },
                      fail: (res) => {},
                    });
                } else {
                    // 扫描失败
                    uni.showToast({
                        title: '扫描失败',
                        icon: 'none'
                    });
                }
            },
            fail() {
                // 调用相机失败
                uni.showToast({
                    title: '已经取消扫码',
                    icon: 'none'
                });
            }
        });
    },
    confirm1() {
      if (!this.value) {
        this.$refs.uNotify.show({
          top: 20,
          type: "error",
          message: "请输入设备号",
          duration: 1000 * 3,
          fontSize: 20,
          safeAreaInsetTop: true,
        });
        return;
      }
      var postData = {
        userId: this.userInfo.userId,
        deviceId: this.value,
      };
      uni.request({
        url: "https://isleepagent.com:444/sleepapp/user/bind", //仅为示例，并非真实接口地址。
        data: postData,
        header: {
          "content-type": "application/json",
          token:uni.getStorageSync('mytoken')
        },
        method: "POST",
        success: (res) => {
          if (res.data.code == 500) {
            this.$refs.uNotify.show({
              top: 20,
              type: "error",
              message: "绑定失败",
              duration: 1000 * 3,
              fontSize: 20,
              safeAreaInsetTop: true,
            });
          }
          if (res.data.code == 200) {
            this.$refs.uNotify.show({
              top: 20,
              type: "success",
              message: "绑定成功",
              duration: 1000 * 3,
              fontSize: 20,
              safeAreaInsetTop: true,
            });
            uni.setStorage({
              key: "userInfo",
              data: res.data.data,
            });
            this.show1 = false;
          }
        },
        fail: (res) => {},
      });
    },
    confirmhj() {
      if (!this.value11) {
        this.$refs.uNotify.show({
          top: 20,
          type: "error",
          message: "请输入设备号",
          duration: 1000 * 3,
          fontSize: 20,
          safeAreaInsetTop: true,
        });
        return;
      }
      var postData = {
        userId: this.userInfo.userId,
        deviceId: this.value11,
      };
      uni.request({
        // url: "http://172.16.20.246:8888/environment/bind", //仅为示例，并非真实接口地址。
        url: "https://isleepagent.com:444/sleepapp/environment/bind", //仅为示例，并非真实接口地址。
        data: postData,
        header: {
          "content-type": "application/json",
          token:uni.getStorageSync('mytoken')
        },
        method: "POST",
        success: (res) => {
          if (res.data.code == 500) {
            this.$refs.uNotify.show({
              top: 20,
              type: "error",
              message: "绑定失败",
              duration: 1000 * 3,
              fontSize: 20,
              safeAreaInsetTop: false,
            });
          }
          if (res.data.code == 200) {
            this.$refs.uNotify.show({
              top: 20,
              type: "success",
              message: "绑定成功",
              duration: 1000 * 3,
              fontSize: 20,
              safeAreaInsetTop: false,
            });
            uni.setStorage({
              key: "userInfo",
              data: res.data.data,
            });
            this.showhj = false;
          }
        },
        fail: (res) => {},
      });
    },
    async confirm() {
      // const res = await this.$myRequest({
      //   url:`/sleepbase/cancel?deviceId=${this.userInfo.deviceId}`
      // });
      uni.removeStorage({
        key: "userInfo",
        success: (res) => {
          uni.showToast({
            title: "退出登录成功！",
            icon: "none",
            duration: 1000,
            mask: true,
          });
          uni.reLaunch({
            url: "/pages/login/login",
          });
        },
        fail: (res) => {},
        complete: (res) => {},
      });
    },
    cancel() {
      this.show = false;
    },
    cancel1() {
      this.show1 = false;
    },
    cancelhj(){
      this.showhj = false;
    },
  },
};
</script>
<style>
::v-deep .u-input{
  border:1px solid #ccc;
}
</style>
<style scoped>

* {
  /* font-family: "黑体" !important; */
}
.content {
  width: 100%;
  height: 100%;
  background: #f6f7fc;
}
.Head {
  width: 100%;
  height: 300rpx;
 background-image:url('data:image/png;base64,');
  background-size: 100% 100%;

  display: flex;
}
.container {
  width: 94%;
  height: 800rpx;
  background: #fff;
  border-radius: 10rpx;
  font-size:20rpx;
  margin-left: 3%;
  margin-top: 50rpx;
  box-shadow: 0px 0px 5px 3px rgba(0, 0, 0, 0.1);
}
</style>

